"""In-process topic broker with retries and a dead letter queue."""
from .filters import compile_topic_regex
from .subscription import Subscription


class Broker:
    def __init__(self):
        self._subscriptions = []
        self.dead_letters = []  # list of (topic, payload, subscription)

    @property
    def dlq(self):
        return self.dead_letters

    def subscribe(self, subscription):
        self._subscriptions.append(subscription)
        return subscription

    def unsubscribe(self, subscription):
        self._subscriptions = [s for s in self._subscriptions if s is not subscription]

    def subscribe_regex(self, pattern, callback, retries=0):
        # BENCHMARK BUG: the compiled regex is never used; the raw pattern
        # string is registered as a literal topic pattern.
        sub = Subscription(pattern, callback, retries=retries)
        self.subscribe(sub)
        return sub

    def publish(self, topic, payload):
        for sub in list(self._subscriptions):
            if not sub.matches(topic):
                continue
            # BENCHMARK BUG: no exception handling — subscriber errors
            # escape publish() and nothing reaches the dead letter queue.
            sub.callback(topic, payload)

