"""Regex filter helpers for advanced subscriptions."""
import re


def compile_topic_regex(pattern):
    """Compile a regex that must match the entire topic string."""
    return re.compile(pattern)

workspace.bus/subscription.py:
"""Subscription model and topic matching."""


class Subscription:
    def __init__(self, topic_pattern, callback, retries=0):
        self.topic_pattern = topic_pattern
        self.callback = callback
        self.retries = int(retries)

    def matches(self, topic):
        return topic_matches(self.topic_pattern, topic)


def topic_matches(pattern, topic):
    """Dot-separated topic match; ``*`` matches exactly one segment."""
    pattern_segments = pattern.split(".")
    topic_segments = topic.split(".")
    if len(pattern_segments) != len(topic_segments):
        return False
    return all(p == "*" or p == t for p, t in zip(pattern_segments, topic_segments))
